import React from "react"
import { Skeleton as HeroSkeleton } from "@heroui/react"
import { WarningCircleIcon } from "@phosphor-icons/react"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { Cluster } from "@sb-components/frames/Cluster/Cluster"

/**
 * `PhaseScarcityNote` ΓÇö the scarcity line for a pricing phase. Every number
 * comes from the backend's `coursePricePreview`; it never fabricates a
 * countdown or seat count, and a phase with no seat cap renders nothing.
 */

/** The course's pricing phases (inlined from `@/modules/types/enums/pricing-phase`). */
export enum PricingPhase {
    /** Opening phase with the fewest seats and the lowest price. */
    Pioneer = "pioneer",
    /** Mid phase after pioneer, still discounted before standard pricing. */
    EarlyBird = "early_bird",
    /** Full-price phase after early-bird seats are gone. */
    Regular = "regular",
}

/** Localised phase display name (inlined from `courseLanding.phase.*`, vi). */
const PHASE_LABEL: Record<PricingPhase, string> = {
    [PricingPhase.Pioneer]: "Pioneer",
    [PricingPhase.EarlyBird]: "Early Bird",
    [PricingPhase.Regular]: "Standard",
}

/**
 * Props for {@link PhaseScarcityNote}. `currentPhase`/`seatsRemaining`/
 * `nextPhasePriceVnd` are REQUIRED unless `isSkeleton` (┬º12b) ΓÇö the price
 * preview hasn't arrived yet, so there is no honest phase/seat fact to state.
 */
export type PhaseScarcityNoteBaseProps =
    (
        | { isSkeleton: true; currentPhase?: PricingPhase; seatsRemaining?: number | null; nextPhasePriceVnd?: number | null }
        | {
            isSkeleton?: false
            /** The course's current pricing phase (shows its label). */
            currentPhase: PricingPhase
            /** Seats left at this phase's price; `null` = unlimited ΓåÆ renders NOTHING. */
            seatsRemaining: number | null
            /** VND price after this phase sells out; `null` = no rise to mention. */
            nextPhasePriceVnd: number | null
        }
    )

/**
 * Honest scarcity line for a paywall. Sits as a DIRECT SIBLING below `PriceTag`
 * (PriceTag handles discounting; scarcity is a different, orthogonal push axis).
 *
 * Only renders when the current phase has a **real seat cap**
 * (`seatsRemaining != null`) ΓÇö an unlimited phase has no honest "rises when"
 * milestone to state, so it stays silent. EVERY number comes from the
 * backend's `coursePricePreview` ΓÇö this file NEVER makes up a countdown or
 * seat count (fake scarcity is a banned dark pattern).
 *
 * @param props - {@link PhaseScarcityNoteBaseProps}
 */
const PhaseScarcityNoteBase = ({
    currentPhase,
    seatsRemaining,
    nextPhasePriceVnd,
    isSkeleton = false,
}: PhaseScarcityNoteBaseProps) => {
    if (isSkeleton) {
        return <HeroSkeleton className="h-4 w-64 max-w-full rounded" />
    }
    // no seat cap at this phase ΓåÆ no honest scarcity reason ΓåÆ stay silent
    if (seatsRemaining == null) {
        return null
    }

    return (
        // Color is set ON THE FRAME; text inside does NOT declare `color`, so it
        // inherits `currentColor` ΓÇö the exact `warning-soft-foreground` tone.
        //
        // This row is ONE TRACK of N elements that wrap ΓçÆ exactly the definition
        // of `Cluster`, and repeated lists go through `items` DATA (children are
        // forbidden).
        //
        // What's gained isn't "fewer classes" but that `gap` is now PINNED to
        // the scale BY TYPE: hand-written it's `gap-2` today, `gap-1.5`
        // tomorrow, nothing stops that.
        <div className="text-warning-soft-foreground">
            <Cluster
                gap={3}
                principle="separator-dot"
                explain="Places a middle-dot separator between short meta peers so the items read as one inline list."
                align="center"
                // The `┬╖` between the two clauses is drawn by the FRAME, not written as a text item.
                // A mark that separates a track's items belongs to the track, the same way a rule
                // does; written as content it also produced a `Separator` node in the structure tree
                // whose link went to the generic Typography story.
                separator
                items={[
                    () => (
                        // ┬º5a: icon matches the FONT-SIZE of the text beside it ΓÇö `sm`
                        // (14px) ΓçÆ `size-3.5`. ┬º5.0a: below `size-5` ΓçÆ force
                        // `weight="bold"` to compensate for the thin strokes.
                        <WarningCircleIcon
                            aria-hidden
                            focusable="false"
                            weight="bold"
                            className="size-3.5 shrink-0"
                        />
                    ),
                    () => (
                        <Typography
                            size="sm"
                            weight="medium"
                            text={`${seatsRemaining} seats left at the ${currentPhase != null ? PHASE_LABEL[currentPhase] : ""} price`}

                        />
                    ),
                    // The next two pieces go TOGETHER (no rise means nothing to separate
                    // it from) ΓÇö but they're still TWO SEPARATE cluster items, since the
                    // `┬╖` mark must be allowed to wrap onto the line with the piece after
                    // it when the row runs tight.
                    ...(nextPhasePriceVnd != null
                        ? [
                            () => (
                                <Typography
                                    size="sm"
                                    text={`price rises to ${nextPhasePriceVnd.toLocaleString("vi-VN")}Γé½ after that`}

                                />
                            ),
                        ]
                        : []),
                ]}
            />
        </div>
    )
}

/** `PhaseScarcityNote.*` ΓÇö single-component namespace ΓçÆ only `.Base`. */
export { PhaseScarcityNoteBase as PhaseScarcityNote }

"use client"

import React, { useCallback, useMemo } from "react"
import { Button, Spinner, Tooltip } from "@heroui/react"
import { ShoppingCartIcon, XIcon } from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import { useCart } from "@/hooks/useCart"
import { useCartEntry } from "@/hooks/useCartEntry"
import type { CourseEntity } from "@/modules/types/entities/course"

/** Props for {@link AddToCartButton}. */
export interface AddToCartButtonProps {
    /** The course this button adds to / removes from the cart. */
    course: CourseEntity
    /**
     * Whether the viewer already owns (is enrolled in) this course. When true the
     * button hides ΓÇö you cannot re-buy a course you own. Omit when unknown (catalog).
     */
    isEnrolled?: boolean
    /**
     * Button variant. Default `"tertiary"` (a lone action beside a course card's
     * View link). Pass `"secondary"` when it sits next to a primary CTA (course
     * detail Enroll), per the button-variant rule.
     */
    variant?: "tertiary" | "secondary"
    /** Render full-width (course-detail CTA cluster). */
    fullWidth?: boolean
    /**
     * Compact icon-only rendering (catalog card footer) ΓÇö a cart/check/trash icon
     * button with a tooltip, so it doesn't compete with the "View course" link.
     * The detail rail keeps the labelled text button (omit this).
     */
    iconOnly?: boolean
}

/**
 * "Add to cart" toggle for a course. Hides itself for FREE courses or courses the
 * viewer already owns (`isEnrolled`). When already in the cart it flips to a single
 * "Remove from cart" button (leading X icon, no trailing icon) ΓÇö `variant="danger-soft"`
 * regardless of the caller's `variant` prop (removing a cart line IS a destructive
 * toggle, just a repeated/low-drama one ΓÇö same family as the repeatable-item delete
 * button, not a lone `danger`-solid action; teacher: "I meant danger-soft", after
 * an earlier pass over-corrected to plain `secondary`). Adding routes through
 * {@link useCartEntry} so a GUEST is sent to the auth modal (with the add replayed
 * after sign-in) instead of hitting the auth-only cart mutation; removing (only
 * reachable once signed in + in cart) goes straight to {@link useCart}. `iconOnly`
 * renders a compact tooltip'd icon button.
 *
 * @param props - {@link AddToCartButtonProps}
 */
export const AddToCartButton = ({
    course,
    isEnrolled = false,
    variant = "tertiary",
    fullWidth = false,
    iconOnly = false,
}: AddToCartButtonProps) => {
    const t = useTranslations()
    const { isInCart, removeFromCart, isMutating } = useCart()
    const { addToCartOrAuth } = useCartEntry()

    // paid = the active-phase price (or the list price) is > 0; free courses are
    // enrolled directly and never enter the cart.
    const isPaid = useMemo(() => {
        const phasePrice = course.pricingPhases?.find(
            (phase) => phase.phase === course.currentPhase,
        )?.price
        const price = phasePrice ?? course.originalPrice ?? 0
        return price > 0
    }, [course.pricingPhases, course.currentPhase, course.originalPrice])

    const inCart = isInCart(course.id)

    const onToggle = useCallback(
        () => {
            if (inCart) {
                void removeFromCart(course.id)
            } else {
                addToCartOrAuth(course.id)
            }
        },
        [inCart, addToCartOrAuth, removeFromCart, course.id],
    )

    // nothing to buy ΓåÆ no cart affordance
    if (isEnrolled || !isPaid) {
        return null
    }

    // compact icon-only (catalog card): a tooltip'd cart/remove icon button.
    if (iconOnly) {
        return (
            <Tooltip>
                <Tooltip.Trigger>
                    <Button
                        isIconOnly
                        variant={inCart ? "danger-soft" : variant}
                        isPending={isMutating}
                        onPress={onToggle}
                        aria-label={inCart ? t("cart.remove") : t("cart.tooltipAdd")}
                    >
                        {isMutating ? (
                            <Spinner size="sm" color="current" />
                        ) : inCart ? (
                            <XIcon className="size-5" />
                        ) : (
                            <ShoppingCartIcon className="size-5" />
                        )}
                    </Button>
                </Tooltip.Trigger>
                <Tooltip.Content>{inCart ? t("cart.remove") : t("cart.tooltipAdd")}</Tooltip.Content>
            </Tooltip>
        )
    }

    return (
        <Button
            variant={inCart ? "danger-soft" : variant}
            fullWidth={fullWidth}
            isPending={isMutating}
            onPress={onToggle}
        >
            {isMutating ? (
                <Spinner size="sm" color="current" />
            ) : inCart ? (
                <XIcon className="size-5" />
            ) : (
                <ShoppingCartIcon className="size-5" />
            )}
            {inCart ? t("cart.remove") : t("cart.add")}
        </Button>
    )
}

"use client"

import React from "react"
import {
    Button,
    Typography,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import { TierLevelIcon } from "@/components/svg/TierLevelIcon"
import { TierCardBase } from "@/components/blocks/commerce/TierCardBase"

/**
 * Free-tier base credit allowance ΓÇö mirrors the backend free auto quota default
 * (`systemConfig.ai.auto`, base 50 / 5h ┬╖ 500 / week). Shown so the free card
 * states its credits like the paid tiers.
 */
const FREE_CREDITS_PER_5H = 50
const FREE_CREDITS_PER_WEEK = 500

/** Props for {@link FreeTierCard}. */
export interface FreeTierCardProps {
    /** True when the user is currently on the free tier (no paid subscription). */
    isCurrent: boolean
    /** First load ΓåÆ the shell rests; the twin that used to mirror this card is gone. */
    isSkeleton?: boolean
}

/**
 * Static free-tier card (not purchasable).
 *
 * Presentational: composes {@link TierCardBase}, showing the "current plan"
 * chip when active, otherwise a disabled CTA. No business logic.
 * @param props - whether the free tier is the user's current plan
 */
export const FreeTierCard = ({
    isCurrent,
    isSkeleton = false}: FreeTierCardProps) => {
    const t = useTranslations()
    return (
        <TierCardBase
            identity={{ tier: "block", component: "FreeTierCard" }}
            isSkeleton={isSkeleton}
            icon={() => (
                <TierLevelIcon
                    level={1}
                    className="size-6 shrink-0 text-accent-soft-foreground"
                />
            )}
            title={t("aiSubscription.free.title")}
            description={t("aiSubscription.free.desc")}
            price={() => (
                <>
                    <Typography type="h3" weight="bold">
                        {t("aiSubscription.free.price")}
                    </Typography>
                    {/* spacer ΓÇö matches paid tiers' USD hint block so CTAs align */}
                    <div
                        className="h-[3lh]"
                        aria-hidden
                    />
                </>
            )}
            features={[
                t("aiSubscription.creditsPer5h", { credits: FREE_CREDITS_PER_5H }),
                t("aiSubscription.creditsPerWeek", { credits: FREE_CREDITS_PER_WEEK }),
            ]}
            isCurrent={isCurrent}
            cta={() => (
                <Button
                    variant="secondary"
                    isDisabled
                    fullWidth
                >
                    {t("aiSubscription.free.cta")}
                </Button>
            )}
        />
    )
}

