import { resolveIdentity, type CallerIdentity } from "@/components/frames/_identity"

/** Props for {@link TierCardBase} (shared shell for {@link TierCard} and {@link FreeTierCard}). */
export interface TierCardBaseProps extends WithClassNames<undefined> {
    /**
     * Tier level icon ΓÇö a BUILDABLE slot (uncalled component), never a built element:
     * an element handed in is already rendered, so this shell cannot decide not to.
     */
    icon: ComponentType
    /** Tier display name ΓÇö text, so it arrives as text. */
    title: string
    /** Optional adornment rendered after the title (e.g. the "popular" chip). */
    badge?: ComponentType
    /** Short tagline shown in a fixed `h-[2lh]` slot so cards align. */
    description?: string
    /** Price block ΓÇö a buildable slot; the tiers lay their price out differently. */
    price: ComponentType
    /** Feature rows shown in the footer, each rendered with a seal-check icon. */
    features: string[]
    /** Whether this tier is the user's current plan. */
    isCurrent: boolean
    /** Call-to-action rendered in place of the "current plan" badge ΓÇö a buildable slot. */
    cta: ComponentType
    /**
     * First load, nothing in hand ΓåÆ every content slot shimmers while the card keeps
     * its own boxes, so the grid does not jump on resolve. The resting shape lives
     * HERE, in the file that owns it: three hand-mirrored twins used to describe this
     * same card and could drift from it independently.
     */
    isSkeleton?: boolean
    /**
     * Caller identity to wear on this shell's root instead of its own ΓÇö pass this
     * when a sentence-tier card roots on this base (see `frames/_identity.ts`).
     */
    identity?: CallerIdentity
}

/** How many feature rows the resting card shows ΓÇö the paid tiers all list two. */
const SKELETON_FEATURE_ROWS = 2

/**
 * Shared shell for an AI subscription tier card (paid or free).
 *
 * Presentational only: renders the icon+title row, fixed-height description,
 * price block, current-plan badge vs CTA, and the feature list footer.
 * Callers ({@link TierCard}, {@link FreeTierCard}) supply tier-specific
 * content (icon, price layout, CTA) and keep their own business logic.
 * @param props - shell content for one tier card
 */
export const TierCardBase = ({
    icon: Icon,
    title,
    badge: Badge,
    description,
    price: Price,
    features,
    isCurrent,
    cta: Cta,
    className,
    isSkeleton = false,
    identity,
}: TierCardBaseProps) => {
    const t = useTranslations()
    // resting rows stand in for whatever the caller would have listed
    const featureRows = isSkeleton
        ? Array.from({ length: SKELETON_FEATURE_ROWS }, (_row, index) => index)
        : features.map((_feature, index) => index)

    return (
        <Card
            className={cn("flex h-full flex-col", className)}
            {...resolveIdentity(identity, { tier: "composite", name: "TierCardBase" })}
        >
            <Card.Content className="flex flex-1 flex-col gap-3">
                {/* icon + tier name (+ optional badge) ΓÇö tight pair */}
                <div className="flex items-center gap-2">
                    {isSkeleton
                        ? <Skeleton className="size-6 shrink-0 rounded-full" />
                        : <Icon />}
                    <Typography type="h5" weight="semibold">
                        {isSkeleton ? <Skeleton className="h-5 w-16 rounded" /> : title}
                    </Typography>
                    {isSkeleton || !Badge ? null : <Badge />}
                </div>
                {/* short tagline ΓÇö fixed slot so cards align */}
                <div className="h-[2lh]">
                    <Typography type="body-sm" color="muted" className="line-clamp-3">
                        {isSkeleton ? <Skeleton className="h-4 w-3/4 rounded" /> : (description ?? "")}
                    </Typography>
                </div>
                <div className="flex flex-col gap-2">
                    {isSkeleton ? <Skeleton className="h-9 w-24 rounded" /> : <Price />}
                </div>
                {isSkeleton ? (
                    <Skeleton className="h-10 w-full rounded-3xl" />
                ) : isCurrent ? (
                    <div className="flex w-full items-center justify-center rounded-3xl bg-success-soft px-3 py-2">
                        <Typography type="body-sm" weight="medium" className="text-success-soft-foreground">
                            {t("aiSubscription.currentPlan")}
                        </Typography>
                    </div>
                ) : <Cta />}
            </Card.Content>
            <Card.Footer>
                {/* feature list ΓÇö seal-check icon + muted text */}
                <div className="flex flex-col gap-2">
                    {featureRows.map((index) => (
                        <div key={index} className="flex items-center gap-2">
                            {isSkeleton
                                ? <Skeleton className="size-5 shrink-0 rounded" />
                                : (
                                    <SealCheckIcon
                                        aria-hidden
                                        className="size-5 shrink-0 text-muted"
                                    />
                                )}
                            <Typography type="body-sm" color="muted">
                                {isSkeleton
                                    ? <Skeleton className="h-4 w-40 max-w-full rounded" />
                                    : features[index]}
                            </Typography>
                        </div>
                    ))}
                </div>
            </Card.Footer>
        </Card>
    )
}

"use client"

import React, {
    useCallback,
} from "react"
import {
    Button,
    Chip,
    Spinner,
    Typography,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import { formatVnd } from "@/modules/utils/format-vnd"
import { formatUsd } from "@/modules/utils/format-usd"
import type { AiSubscriptionTier } from "@/modules/api/graphql/queries/types/ai-subscription-tiers"
import { usePaymentOverlayState } from "@/hooks/zustand/overlay/hooks"
import { PaymentFlow } from "@/modules/types/payment"
import { TierLevelIcon } from "@/components/svg/TierLevelIcon"
import { TierCardBase } from "@/components/blocks/commerce/TierCardBase"

/** Props for {@link TierCard} (list item ΓÇö per-item tier data only). */
export interface TierCardProps {
    /** Tier this card represents. */
    /** The tier this card sells. Absent only while {@link TierCardProps.isSkeleton}. */
    tier?: AiSubscriptionTier
    /** Whether this tier is the user's current plan. */
    isCurrent: boolean
    /** First load ΓåÆ the shell rests; the twin that used to mirror this card is gone. */
    isSkeleton?: boolean
}

/** Placeholder for the resting card's slots ΓÇö the shell shimmers over every one of them. */
const EmptySlot = () => null

/**
 * One purchasable AI subscription tier card.
 *
 * List item: receives its own tier data + current flag; self-opens the shared
 * payment overlay for the buy action via {@link usePaymentOverlayState}.
 * Composes {@link TierCardBase} for the shared shell (surface color, no
 * shadow per global, `rounded-3xl`); the popular tier gets an accent border + ring.
 * @param props - tier, current state
 */
export const TierCard = ({
    tier,
    isCurrent,
    isSkeleton = false}: TierCardProps) => {
    const t = useTranslations()
    const { open: openPaymentModal } = usePaymentOverlayState()

    const onPress = useCallback(
        () => {
            if (!tier) {
                return
            }
            openPaymentModal({
                flow: PaymentFlow.AiSubscription,
                tier: tier.tier,
            })
        },
        [
            tier,
            openPaymentModal,
        ],
    )
    // Resting: the SHELL draws every box, so nothing here needs a tier yet. Returning
    // early is what lets the loaded branch below read `tier` without a guard on each line.
    if (isSkeleton || !tier) {
        return (
            <TierCardBase
                identity={{ tier: "block", component: "TierCard" }}
                isSkeleton
                icon={EmptySlot}
                title=""
                price={EmptySlot}
                features={[]}
                isCurrent={false}
                cta={EmptySlot}
            />
        )
    }

    // ascending tier level ΓÇö Plus=2, Pro=3, Max=4 (highlighted bars)
    const tierLevel = tier.tier === "max"
        ? 4
        : tier.tier === "pro"
            ? 3
            : 2
    return (
        <TierCardBase
            identity={{ tier: "block", component: "TierCard" }}
            className={tier.popular ? "border-accent ring-2 ring-accent/30" : undefined}
            icon={() => (
                <TierLevelIcon
                    level={tierLevel}
                    className="size-6 shrink-0 text-accent-soft-foreground"
                />
            )}
            title={tier.displayName}
            badge={tier.popular
                ? () => (
                    <Chip
                        size="sm"
                        color="accent"
                        variant="soft"
                    >
                        <Chip.Label>{t("aiSubscription.popular")}</Chip.Label>
                    </Chip>
                )
                : undefined}
            description={tier.description ?? ""}
            price={() => (
                <>
                    {/* VND number prominent + "/month" */}
                    <div className="flex flex-wrap items-baseline gap-x-2">
                        <Typography type="h3" weight="bold">
                            {formatVnd(tier.priceVnd)}
                        </Typography>
                        <Typography type="body-sm" color="muted">
                            {t("aiSubscription.perMonth")}
                        </Typography>
                    </div>
                    {/* secondary USD line ΓÇö what international gateways charge */}
                    <div className="h-[3lh]">
                        <Typography type="body-sm" color="muted">
                            {t("aiSubscription.priceUsdHint", { amount: formatUsd(tier.priceUsd) })}
                        </Typography>
                    </div>
                </>
            )}
            features={[
                t("aiSubscription.creditsPer5h", { credits: tier.creditsPer5h }),
                t("aiSubscription.creditsPerWeek", { credits: tier.creditsPerWeek }),
            ]}
            isCurrent={isCurrent}
            cta={() => (
                <Button
                    variant="primary"
                    fullWidth
                    onPress={onPress}
                >
                    {({ isPending }) => (
                        <>
                            {isPending ? (
                                <Spinner
                                    color="current"
                                    size="sm"
                                />
                            ) : null}
                            {t("aiSubscription.buy")}
                        </>
                    )}
                </Button>
            )}
        />
    )
}

"use client"

import React from "react"
import { FreeTierCard } from "@/components/blocks/commerce/FreeTierCard"
import { TierCard } from "@/components/blocks/commerce/TierCard"
import { useQueryAiSubscriptionTiersSwr } from "@/hooks/swr/api/graphql/queries/useQueryAiSubscriptionTiersSwr"
import { useQueryMyAiSettingsSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyAiSettingsSwr"

/** How many paid cards the resting grid holds ΓÇö the free card plus these fills both columns. */
const SKELETON_PAID_CARDS = 3

/** Props for {@link TierGrid}. */
export interface TierGridProps {
    /**
     * First load, nothing in hand ΓåÆ the SAME cards render resting, in the SAME grid.
     * A separate `AiSubscriptionSkeleton` used to mirror this layout by hand, along
     * with one twin per card; all three are gone.
     */
    isSkeleton?: boolean
}

/**
 * Responsive grid of subscription tiers: the static free tier followed by the
 * purchasable paid tiers.
 *
 * Reads eligible tiers from the AI subscription SWR singleton and the user's
 * current tier from the AI settings singleton. Each {@link TierCard} is a list
 * item that self-opens the payment overlay for the buy action.
 *
 * @param props - {@link TierGridProps}
 */
export const TierGrid = ({
    isSkeleton = false}: TierGridProps) => {
    const { data: tiersData } = useQueryAiSubscriptionTiersSwr()
    const { data: mySettings } = useQueryMyAiSettingsSwr()

    /** Purchasable paid tiers from the query (empty until loaded). */
    const tiers = tiersData ?? []
    /** The user's current tier slug, or null for the free tier. */
    const currentTier = mySettings?.tier ?? null

    return (
        <div className={"grid grid-cols-1 gap-6 @app-sm:grid-cols-2"}>
            <FreeTierCard isCurrent={currentTier === null} isSkeleton={isSkeleton} />
            {isSkeleton
                ? Array.from({ length: SKELETON_PAID_CARDS }, (_card, index) => (
                    <TierCard
                        key={`pending-${index}`}
                        isSkeleton
                        isCurrent={false}
                    />
                ))
                : tiers.map((tier) => (
                    <TierCard
                        key={tier.tier}
                        tier={tier}
                        isCurrent={currentTier === tier.tier}
                    />
                ))}
        </div>
    )
}

import React from "react"
import { ArrowRightIcon, LockIcon } from "@phosphor-icons/react"
import { type SkeletonProps } from "@/components/frames/_slot"
import { IconTile } from "@/components/atoms/display/IconTile"
import { PriceTagProminent, type PriceBreakdown } from "@/components/blocks/commerce/PriceTag"
// The NON-legacy version (`designs/commerce/ΓÇª`) ΓÇö the `_legacy` version of the same
// name still exists but is a dead end; screens are forbidden from touching `_legacy`
// so every link in the chain has to move off it.
import { PhaseScarcityNote } from "@/components/blocks/commerce/PhaseScarcityNote"
import { Button } from "@/components/atoms/buttons/Button"
import { Typography } from "@/components/atoms/text/Typography"
import { TitledText } from "@/components/composites/text/TitledText"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { StackH, StackV } from "@/components/frames/Stack"
import type { QueryCoursePricePreviewData } from "@/modules/api/graphql/queries/types/course-price-preview"

/** Props for {@link _TrialConversionStrip} ΓÇö presentational; all text + price resolved, no fetch/store/i18n. */
export interface TrialConversionStripProps {
    /** Card title (already localized). */
    title: string
    /** Supporting line under the title ΓÇö the connected file already picked the goal-gradient vs generic copy. */
    description: string
    /** Enroll CTA label (already localized). */
    cta: string
    /** Resolved pre-checkout price; omitted/null ΓåÆ the price line is skipped. */
    price?: QueryCoursePricePreviewData | null
    /**
     * `true` while the price is still fetching ΓåÆ the price column shimmers instead of
     * showing an empty gap, KEEPING its line boxes so nothing jumps in layout. The
     * header (icon/title/description) and the CTA never depend on the price fetch, so
     * they always render their real content.
     */
    isSkeleton?: boolean
    /** Open the shared payment modal in the course-enroll flow. */
    onEnroll: () => void
}

/**
 * Trial ΓåÆ enroll conversion strip on the content-home ΓÇö the presentational half of
 * {@link import("./index").TrialConversionStrip}. Three honest levers: (1) loss-aversion copy,
 * (2) real pricing-phase scarcity via {@link PhaseScarcityNote}, (3) an outcome-framed enroll CTA.
 * Every number is handed in resolved ΓÇö nothing fabricated. See `design/storybook/architecture/split.md`.
 *
 * @param props - {@link TrialConversionStripProps}
 */
export const _TrialConversionStrip = ({
    title,
    description,
    cta,
    price,
    isSkeleton = false,
    onEnroll,
}: TrialConversionStripProps) => {
    const breakdown: PriceBreakdown | undefined = price
        ? {
            phase: price.phasePriceVnd,
            loyaltyPercent: price.discountPercent,
        }
        : undefined

    // Header never rests ΓÇö title/description already arrived as resolved strings
    // (i18n + the outline), not a fetch, so there is nothing here to shimmer.
    const headerRow = (
        <StackH gap={4} principle="content-row"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            align="center" items={[
                () => <IconTile icon={LockIcon} tone="accent" size="sm" />,
                () => <TitledText classNames={["flex-1"]} title={title} subtitle={description} />,
            ]} />
    )

    // The scarcity line is a CAPTION OF THE PRICE ΓÇö price + scarcity are one cluster,
    // this is an intra-cluster seam (not the wider seam around the whole card).
    const priceColumn = (
        <StackV gap={4} isSkeleton={isSkeleton} items={
            isSkeleton && !price ? [
                // The header + CTA render instantly, but the price is a second fetch ΓÇö
                // mirror the price line instead of showing an empty gap until it lands.
                () => <Typography size="h4" isSkeleton classNames={["w-1/3"]} />,
                () => <Typography size="xs" isSkeleton />,
            ] : price?.discountedPriceVnd != null ? [
                ({ isSkeleton }: SkeletonProps) => (
                    <PriceTagProminent
                        isSkeleton={isSkeleton}
                        discounted={price.discountedPriceVnd}
                        original={price.originalPriceVnd}
                        breakdown={breakdown}
                    />
                ),
                ({ isSkeleton }: SkeletonProps) => (
                    <PhaseScarcityNote
                        isSkeleton={isSkeleton}
                        currentPhase={price.currentPhase}
                        seatsRemaining={price.seatsRemainingInCurrentPhase}
                        nextPhasePriceVnd={price.nextPhasePriceVnd}
                    />
                ),
            ] : []
        } />
    )

    // Price is a NUMBER ΓÇö shrinking it means nothing, unlike a long title that can
    // truncate. The row wraps when tight (`StackH`): the button drops to the next
    // line instead of the price getting squeezed.
    const footerRow = (
        <StackH gap={6} principle="block-boundary"
            explain="Block-to-block spacing ΓÇö not group-boundary, because this separates major blocks rather than nested section groups."
            align="end" justify="between" at="sm" items={[
                () => priceColumn,
                // ATOM `Button`, NOT the legacy HeroUI one ΓÇö `suffixIcon` takes a COMPONENT
                // REF, the atom forces scale + weight; the CTA is never gated on the price
                // fetch, so it does not take `isSkeleton`.
                () => (
                    <Button
                        variant="primary"
                        size="lg"
                        label={cta}
                        suffixIcon={ArrowRightIcon}
                        iconSlide
                        onPress={onEnroll}
                    />
                ),
            ]} />
    )

    return (
        // The frame owns radius/shadow/padding from ONE source: `SurfaceCard`.
        <SurfaceCard identity={{ tier: "block", component: "TrialConversionStrip" }}
            body={() => (
                <StackV gap={6} items={[
                    () => headerRow,
                    () => footerRow,
                ]} />
            )}
        />
    )
}

"use client"

import React, {
    useCallback,
} from "react"
import type {
    ReactNode,
} from "react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useRouter,
} from "next/navigation"
import { ResponsiveBreadcrumb } from "@/components/blocks/navigation/ResponsiveBreadcrumb"
import type { ResponsiveBreadcrumbItem } from "@/components/blocks/navigation/ResponsiveBreadcrumb"
import { pathConfig } from "@/resources/path"

/** Props for {@link SettingsBreadcrumb}. */
export interface SettingsBreadcrumbProps {
    /** The current page label ΓÇö the last, read-only crumb. */
    current: ReactNode
}

/**
 * Shared settings/profile breadcrumb trail: `Home ΓÇ║ Profile ΓÇ║ Settings ΓÇ║ <current>`
 * (the last crumb is read-only). DRY-replaces the hand-rolled trail every settings
 * page used to repeat, so every page under `/profile/settings/*` shows the same
 * tier-1 breadcrumb. Mirrors the trail the edit/security pages already build.
 *
 * @param props - {@link SettingsBreadcrumbProps}
 */
export const SettingsBreadcrumb = ({
    current,
}: SettingsBreadcrumbProps) => {
    const t = useTranslations()
    const router = useRouter()
    const locale = useLocale()

    /** Navigate to the home page (breadcrumb root). */
    const onNavigateHome = useCallback(
        () => router.push(pathConfig().locale().build()),
        [
            router,
        ],
    )
    /** Navigate to the profile (breadcrumb parent). */
    const onNavigateProfile = useCallback(
        () => router.push(pathConfig().locale(locale).profile().build()),
        [
            router,
            locale,
        ],
    )
    /** Navigate to the settings root (breadcrumb parent of every settings page). */
    const onNavigateSettings = useCallback(
        () => router.push(pathConfig().locale(locale).profile().settings().build()),
        [
            router,
            locale,
        ],
    )

    const items: Array<ResponsiveBreadcrumbItem> = [
        { key: "home", label: t("nav.home"), onPress: onNavigateHome },
        { key: "profile", label: t("nav.profile"), onPress: onNavigateProfile },
        { key: "settings", label: t("nav.settings"), onPress: onNavigateSettings },
        { key: "current", label: current },
    ]

    return <ResponsiveBreadcrumb items={items} />
}
